package com.mediconnect.doctor.api;
import com.mediconnect.doctor.application.DoctorService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/doctors") @Tag(name="Admin Doctors") @SecurityRequirement(name="bearerAuth") public class AdminDoctorController { private final DoctorService service; public AdminDoctorController(DoctorService service){this.service=service;} @PostMapping @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Create a doctor",description="ADMIN-only endpoint that creates a ROLE_DOCTOR account and medical profile.") public DoctorResponse create(@Valid @RequestBody CreateDoctorRequest request){return service.createDoctor(request);} }
